import { useState, useEffect } from 'react';
import { useNavigate, Link, Routes, Route } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';
import '@fortawesome/fontawesome-free/css/all.min.css';

import Home from './Home';
import Students from './Students';
import Courses from './Courses';
import Questions from './Questions';

const styles = {
  container: {
    display: 'flex',
    minHeight: '100vh',
    background: '#f4f6f9',
    fontFamily: 'Segoe UI, sans-serif'
  },

  sidebar: {
    width: '250px',
    background: '#111827',
    color: '#fff',
    display: 'flex',
    flexDirection: 'column',
    paddingTop: '20px'
  },

  logo: {
    textAlign: 'center',
    marginBottom: '30px'
  },

  logoImg: {
    width: '120px'
  },

  nav: {
    listStyle: 'none',
    padding: 0
  },

  navItem: {
    padding: '14px 25px',
    display: 'flex',
    alignItems: 'center',
    color: '#9ca3af',
    textDecoration: 'none',
    fontSize: '15px',
    transition: '0.2s'
  },

  navItemActive: {
    background: '#1f2937',
    color: '#fff',
    borderLeft: '4px solid #3b82f6'
  },

  navIcon: {
    marginRight: '12px',
    fontSize: '16px'
  },

  main: {
    flex: 1,
    padding: '25px'
  },

  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '25px'
  },

  title: {
    fontSize: '22px',
    fontWeight: '600',
    color: '#111827'
  },

  logoutBtn: {
    background: '#ef4444',
    border: 'none',
    color: '#fff',
    padding: '6px 14px',
    borderRadius: '6px'
  }
};

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('dashboard');

  useEffect(() => {
    const path = window.location.pathname;
    if (path === '/admin') setActiveTab('dashboard');
    else if (path === '/admin/students') setActiveTab('students');
    else if (path === '/admin/courses') setActiveTab('courses');
    else if (path === '/admin/questions') setActiveTab('questions');
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  const menu = [
    { id: 'dashboard', label: 'Dashboard', icon: 'fa-home', path: '/admin' },
    { id: 'students', label: 'Students', icon: 'fa-users', path: '/admin/students' },
    { id: 'courses', label: 'Courses', icon: 'fa-book', path: '/admin/courses' },
    { id: 'questions', label: 'Questions', icon: 'fa-question-circle', path: '/admin/questions' }
  ];

  return (
    <div style={styles.container}>

      {/* SIDEBAR */}
      <div style={styles.sidebar}>
        <div style={styles.logo}>
          <img src="/logo.png" alt="logo" style={styles.logoImg} />
        </div>

        <ul style={styles.nav}>
          {menu.map(item => (
            <li key={item.id}>
              <Link
                to={item.path}
                onClick={() => setActiveTab(item.id)}
                style={{
                  ...styles.navItem,
                  ...(activeTab === item.id ? styles.navItemActive : {})
                }}
              >
                <i className={`fa ${item.icon}`} style={styles.navIcon}></i>
                {item.label}
              </Link>
            </li>
          ))}
        </ul>
      </div>

      {/* MAIN */}
      <div style={styles.main}>

        {/* HEADER */}
        <div style={styles.header}>
          <div style={styles.title}>
            {activeTab === 'dashboard' && 'Dashboard'}
            {activeTab === 'students' && 'Manage Students'}
            {activeTab === 'courses' && 'Manage Courses'}
            {activeTab === 'questions' && 'Manage Questions'}
          </div>

          <button onClick={handleLogout} style={styles.logoutBtn}>
            Logout
          </button>
        </div>

        {/* CONTENT */}
        <Routes>
          <Route index element={<Home />} />
          <Route path="students" element={<Students />} />
          <Route path="courses" element={<Courses />} />
          <Route path="questions" element={<Questions />} />
        </Routes>

      </div>
    </div>
  );
}
